function SearchBar() {
  const [focused, setFocused] = useState(false)
  const inputRef = useRef<HTMLInputElement>(null)

  useKeyBind('/', () => {
    inputRef.current?.focus()
    setFocused(true)
  }, { ignoreInputs: true })

  useKeyBind('escape', () => {
    inputRef.current?.blur()
    setFocused(false)
  }, { enabled: focused })

  return <input ref={inputRef} placeholder="Search..." />
